INSERT INTO kpi_items ("id", "company_id", "no", "name", "category_id", "measure_type", "unit", "direction", "formula", "formula_note", "intent", "data_source", "judge_timing", "a_type", "a_standard", "controllability", "a_rationale", "remarks", "is_fixed_slot", "is_monetary", "is_provisional", "provisional_note", "is_active", "created_at", "updated_at") VALUES
('kpi_template_1', 'cmp_template', 1, '等級要件達成率', NULL, '個人実績', '%', 'higher', 'q1_1 ÷ 【等級別の半期目標設定上限数】 × 100', '分母は等級から自動決定：Beginner=5／Regular=5／Chief=5／AM Ⅰ=3／AM Ⅱ=2／Manager Ⅰ=2／Manager Ⅱ=2（等級要件シートより）', '個人がどのくらい等級を上げられたか', '目標設定シート', '9月末・3月末時点', '完全達成型', '100%以上', '内部完結', '設定した等級要件をすべて達成して初めてA。目標設定時に本人が数を決めるため、完全に自分で制御できる', '元シートで定義済み。全等級の配点調整弁', 1, 0, 0, NULL, 1, 1786352400000, 1735689600000),
('kpi_template_2', 'cmp_template', 2, 'ヒヤリ報告件数', 'cat_template_safety', '個人・事業所実績', '件', 'higher', 'q2_1 + q2_2 + q2_3（合計件数をそのまま実績値とする）', 'Regular/Chief＝本人が報告した件数、AM/Manager＝事業所全体で報告された件数。フォームの説明文を等級で切り替える', 'Reg/Chiefは個人で何件報告したか。AM/Managerは事業所全体で何件報告させられたか', 'ヒヤリハット報告書', '9月末・3月末時点', '基準超過型', '24件以上', '内部完結', '必達ライン18件（月3件）はB。Aは月4件ペースの24件。件数は自分の行動だけで積み上がるため全A条件でも到達可能', 'A群B群C群それぞれ月1件＝月3件×6ヶ月＝18件が基準ライン。群別に入力させることで群の偏りも把握できる', 0, 0, 0, NULL, 1, 1786352400000, 1735689600000),
('kpi_template_3', 'cmp_template', 3, '報告書送付率', 'cat_template_quality', '事業所実績', '%', 'higher', 'q3_1 ÷ q3_2 × 100', NULL, '事業所で何％の報告書を送付したか', '報告書格納フォルダ（作成依頼）宛先・送付日', '9月末・3月末時点', '完全達成型', '100%以上', '内部完結', '送付漏れゼロで初めてA。送付は自分の手元で完結する作業のため100%を要求できる', '元定義は「×人数÷事業所登録者数」だが、フォームからの自動採点のため『送付済み件数÷送付必要件数』に分解した', 0, 0, 0, NULL, 1, 1786352400000, 1735689600000),
('kpi_template_4', 'cmp_template', 4, '昇給率', 'cat_template_hr', '個人実績', '%', 'higher', 'q4_1 ÷ q4_2 × 100', NULL, 'Reg以下の人をどのくらい昇給させられたか AND 自身も昇給したか', '目標設定シート', '9月末・3月末時点', '完全達成型', '100%以上', '内部完結', '昇給可能額を全額実現して初めてA。部下の育成が伴うため難度は高いが、上位等級の中核業務', '元シートで定義済み', 0, 0, 0, NULL, 1, 1786352400000, 1735689600000),
